# Surah Al-An'am (chapter 6) — part 8: ayat 74-83 (IDs 863-872)
SURAH = 6

ENTRIES = {
863: (
"اور جب — ابراہیمؑ نے اپنے باپ آزر سے کہا: کیا تو بتوں (بت) کو — رب — بناتا ہے — بے شک میں — تجھے — اور تیری قوم کو واضح گمراہی میں دیکھتا ہوں",
"""۱۔ ابراہیمؑ — آزر کو شرک سے روکا۔
۲۔ ’’وَإِذْ قَالَ إِبْرَاهِيمُ لِأَبِيهِ آزَرَ أَتَتَّخِذُ أَصْنَامًا آلِهَۃً‘‘ — اور جب — ابراہیمؑ نے اپنے باپ آزر سے کہا: کیا تو بتوں (بت) کو — رب — بناتا ہے — یعنی ابراہیمؑ نے — اپنے — باپ کو بھی — شرک سے — منع کیا۔
۳۔ ’’إِنِّي أَرَاكَ وَقَوْمَكَ فِي ضَلَالٍ مُّبِينٍ‘‘ — بے شک میں — تجھے — اور تیری قوم کو واضح گمراہی میں دیکھتا ہوں — یعنی بت پرستی — واضح گمراہی ہے۔
۴۔ عملی سبق: حق کی خاطر — اپنے اعزاء کو بھی — ٹوکو — تعلقات سے فوقیت ایمان کو دو۔"""
),
864: (
"اور اسی طرح ہم — ابراہیمؑ کو — آسمانوں اور زمین کی بادشاہی دکھاتے ہیں — اور اسی لیے کہ وہ — یقین کرنے والوں — میں سے ہو",
"""۱۔ ابراہیمؑ کو — عالمِ غیب کی بادشاہی — دکھائی گئی۔
۲۔ ’’وَكَذَٰلِكَ نُرِي إِبْرَاهِيمَ مَلَكُوتَ السَّمَاوَاتِ وَالْأَرْضِ وَلِيَكُونَ مِنَ الْمُوقِنِينَ‘‘ — اور اسی طرح ہم — ابراہیمؑ کو — آسمانوں اور زمین کی بادشاہی دکھاتے ہیں — اور اسی لیے کہ وہ — یقین کرنے والوں — میں سے ہو — یعنی اللہ نے ابراہیمؑ کو — روحانیت کا معراج — عطا کیا۔
۳۔ عملی سبق: اللہ کی عظمت پر یقین لاؤ؛ ابراہیمؑ کی راہ پر چلو۔"""
),
865: (
"پس جب — اس پر — رات چھا گئی — اس نے ایک ستارہ دیکھا — اس نے کہا: یہ — میرا — رب ہے — پھر جب وہ ڈوب گیا — اس نے کہا: میں ڈوبنے والوں (آفلین) کو پسند نہیں کرتا",
"""۱۔ ابراہیمؑ — ستارہ دیکھ کر استدلال — کرتے ہیں۔
۲۔ ’’فَلَمَّا جَنَّ عَلَيْهِ اللَّيْلُ رَأَىٰ كَوْكَبًا قَالَ هَٰذَا رَبِّي‘‘ — پس جب — اس پر — رات چھا گئی — اس نے ایک ستارہ دیکھا — اس نے کہا: یہ — میرا — رب ہے — یعنی ابراہیمؑ — قوم کے خیال میں — منطق سے — سوچتے ہیں (بحث ومباحثہ کے لیے)۔
۳۔ ’’فَلَمَّا أَفَلَ قَالَ لَا أُحِبُّ الْآفِلِينَ‘‘ — پھر جب وہ ڈوب گیا — اس نے کہا: میں ڈوبنے والوں (آفلین) کو پسند نہیں کرتا — یعنی جب ستارہ ڈوب گیا — تو ابراہیمؑ نے کہا — میں غروب ہونے والے رب کو نہیں مانتا۔
۴۔ عملی سبق: ستارے — ڈوب جاتے ہیں — اس — لیے وہ رب نہیں ہو سکتے؛ غور و فکر سے حق پہچانو۔"""
),
866: (
"پھر جب اس نے چاند — بلند ہوتا — دیکھا — اس نے کہا: یہ — میرا — رب ہے — پھر جب وہ ڈوب گیا — اس نے کہا: اگر میرا رب — مجھے ہدایت نہیں دے گا تو میں — گمراہ — لوگوں میں سے ہو جاؤں گا",
"""۱۔ چاند — بھی — ڈوب جاتا ہے — رب نہیں۔
۲۔ ’’فَلَمَّا رَأَى الْقَمَرَ بَازِغًا قَالَ هَٰذَا رَبِّي فَلَمَّا أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِي رَبِّي لَأَكُونَنَّ مِنَ الْقَوْمِ الضَّالِّينَ‘‘ — پھر جب اس نے چاند — بلند ہوتا — دیکھا — اس نے کہا: یہ — میرا — رب ہے — پھر جب وہ ڈوب گیا — اس نے کہا: اگر میرا رب — مجھے ہدایت نہیں دے گا تو میں — گمراہ — لوگوں میں سے ہو جاؤں گا — یعنی ابراہیمؑ — خود اللہ سے ہدایت مانگتے ہیں۔
۳۔ عملی سبق: چاند اور ستارے — رب نہیں ہو سکتے؛ اللہ سے ہدایت مانگو۔"""
),
867: (
"پھر جب اس نے سورج — بلند ہوتا — دیکھا — اس نے کہا: یہ — میرا — رب ہے — یہ سب سے بڑا ہے — پھر جب وہ ڈوب گیا — اس نے کہا: اے میری قوم! میں — جو تم شریک بناتے ہو — اس سے — بری — ہوں",
"""۱۔ سورج بھی — ڈوب جاتا ہے۔
۲۔ ’’فَلَمَّا رَأَى الشَّمْسَ بَازِغَۃً قَالَ هَٰذَا رَبِّي هَٰذَا أَكْبَرُ‘‘ — پھر جب اس نے سورج — بلند ہوتا — دیکھا — اس نے کہا: یہ — میرا — رب ہے — یہ سب سے بڑا ہے — یعنی ابراہیمؑ نے — سب سے بڑا ستارہ — بھی آزمایا۔
۳۔ ’’فَلَمَّا أَفَلَتْ قَالَ يَا قَوْمِ إِنِّي بَرِيءٌ مِّمَّا تُشْرِكُونَ‘‘ — پھر جب وہ ڈوب گیا — اس نے کہا: اے میری قوم! میں — جو تم شریک بناتے ہو — اس سے — بری — ہوں — یعنی سورج بھی آفل تھا — تو — ابراہیمؑ نے شرک سے برات کا اعلان کیا۔
۴۔ عملی سبق: سب سے بڑی چیز — رب نہیں ہو سکتی؛ شرک سے برات کا اعلان کرو۔"""
),
868: (
"میں نے — اپنا رخ — اسی کی طرف پھیرا — جو آسمانوں اور زمین کو پیدا کرنے والا ہے — یکسو ہو کر — اور — میں — مشرکوں میں سے نہیں ہوں",
"""۱۔ ابراہیمؑ کا توحید کا اعلان۔
۲۔ ’’إِنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ‘‘ — میں نے — اپنا رخ — اسی کی طرف پھیرا — جو آسمانوں اور زمین کو پیدا کرنے والا ہے — یکسو ہو کر — اور — میں — مشرکوں میں سے نہیں ہوں — یعنی ابراہیمؑ نے شرک سے مکمل برات کا اعلان کیا۔
۳۔ عملی سبق: اللہ کو واحد خالق مانو؛ توحید پر ڈٹے رہو؛ شرک سے برات کا اعلان کرو۔"""
),
869: (
"اور اس کی قوم نے اس سے — مجادلہ — کیا — اس نے کہا: کیا تم — اللہ کے بارے میں — مجھ سے مجادلہ کرتے ہو — حالانکہ اس نے مجھے ہدایت دی — اور میں — جو تم — اس کے ساتھ — شریک بناتے ہو — ان — سے — نہیں ڈرتا — مگر یہ کہ — میرا رب — کچھ — چاہے — میرے رب کا علم — ہر چیز پر — وسیع ہے — کیا تم — غور — نہیں کرتے",
"""۱۔ قوم نے ابراہیمؑ سے مجادلہ کیا۔
۲۔ ’’وَحَاجَّهُ قَوْمُهُ قَالَ أَتُحَاجُّونِّي فِي اللّٰہِ وَقَدْ هَدَانِ‘‘ — اور اس کی قوم نے اس سے — مجادلہ — کیا — اس نے کہا: کیا تم — اللہ کے بارے میں — مجھ سے مجادلہ کرتے ہو — حالانکہ اس نے مجھے ہدایت دی — یعنی ابراہیمؑ نے قوم کو منطق سے جواب دیا۔
۳۔ ’’وَلَا أَخَافُ مَا تُشْرِكُونَ بِهِ إِلَّا أَن يَشَاءَ رَبِّي شَيْئًا‘‘ — اور میں — جو تم — اس کے ساتھ — شریک بناتے ہو — ان — سے — نہیں ڈرتا — مگر یہ کہ — میرا رب — کچھ — چاہے — یعنی اللہ کے سوا — کسی سے خوف نہیں — سوائے اللہ کی مرضی کے۔
۴۔ ’’وَسِعَ رَبِّي كُلَّ شَيْءٍ عِلْمًا أَفَلَا تَتَذَكَّرُونَ‘‘ — میرے رب کا علم — ہر چیز پر — وسیع ہے — کیا تم — غور — نہیں کرتے — یعنی اللہ کا علم — بے انداز ہے۔
۵۔ عملی سبق: اللہ کی ہدایت پر بھروسہ کرو؛ اللہ کے سوا — کسی سے خوف مت کرو۔"""
),
870: (
"اور میں کیسے — ان — سے ڈروں — جو تم — اس کے ساتھ — شریک بناتے ہو — اور تم — نہیں ڈرتے — کہ تم — اللہ — کے ساتھ — شریک بناتے ہو — اس — کے — لیے جس پر اللہ نے — تمہیں — کوئی — اختیار — نہیں — اتارا — پس کون سا گروہ — امن — کا — زیادہ — مستحق ہے — اگر تم — جانتے ہو",
"""۱۔ شرک — سب سے بڑا خطرہ۔
۲۔ ’’وَكَيْفَ أَخَافُ مَا أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُمْ بِاللّٰہِ مَا لَمْ يُنَزِّلْ بِهِ عَلَيْكُمْ سُلْطَانًا‘‘ — اور میں کیسے — ان — سے ڈروں — جو تم — اس کے ساتھ — شریک بناتے ہو — اور تم — نہیں ڈرتے — کہ تم — اللہ — کے ساتھ — شریک بناتے ہو — اس — کے — لیے جس پر اللہ نے — تمہیں — کوئی — اختیار — نہیں — اتارا — یعنی جس شرک پر اللہ نے — کوئی دلیل — نہیں اتاری — اس سے ڈرنا چاہیے۔
۳۔ ’’فَأَيُّ الْفَرِيقَيْنِ أَحَقُّ بِالْأَمْنِ إِن كُنتُمْ تَعْلَمُونَ‘‘ — پس کون سا گروہ — امن — کا — زیادہ — مستحق ہے — اگر تم — جانتے ہو — یعنی توحید والا — امن — شرک والا — ناامن۔
۴۔ عملی سبق: اللہ کے ساتھ شرک سے ڈرو؛ توحید والے امن میں رہو۔"""
),
871: (
"جو — ایمان لائے اور اپنے ایمان کو — ظلم — سے — ملاوٹ — نہیں کی — یہی — لوگ — امن کے مستحق ہیں — اور یہی — ہدایت یافتہ ہیں",
"""۱۔ ایمان + ظلم سے پاک — امن کی ضمانت۔
۲۔ ’’الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُم بِظُلْمٍ أُولَٰئِكَ لَهُمُ الْأَمْنُ وَهُمْ مُهْتَدُونَ‘‘ — جو — ایمان لائے اور اپنے ایمان کو — ظلم — سے — ملاوٹ — نہیں کی — یہی — لوگ — امن کے مستحق ہیں — اور یہی — ہدایت یافتہ ہیں — یعنی جس ایمان میں ظلم (شرک) — نہ ہو — وہی ایمان باعثِ امن ہے۔
۳۔ عملی سبق: ایمان کو ظلم (شرک) — سے پاک — رکھو؛ امن اور ہدایت — ایمان میں ہے۔"""
),
872: (
"اور یہ — ہماری — دلیل ہے — ہم — نے — ابراہیمؑ — کو — اس — کی — قوم پر — دی — ہم — جس کو چاہتے ہیں — درجات — بلند کرتے ہیں — بے شک تمہارا رب — حکمت والا — جاننے والا ہے",
"""۱۔ ابراہیمؑ کی دلیل — ہماری — دی ہوئی — تھی۔
۲۔ ’’وَتِلْكَ حُجَّتُنَا آتَيْنَاهَا إِبْرَاهِيمَ عَلَىٰ قَوْمِهِ نَرْفَعُ دَرَجَاتٍ مَّن نَّشَاءُ‘‘ — اور یہ — ہماری — دلیل ہے — ہم — نے — ابراہیمؑ — کو — اس — کی — قوم پر — دی — ہم — جس کو چاہتے ہیں — درجات — بلند کرتے ہیں — یعنی ابراہیمؑ کی دلیل — اللہ کی — طرف سے — تھی — اللہ — جسے چاہے — بلند کرتا ہے۔
۳۔ ’’إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ‘‘ — بے شک تمہارا رب — حکمت والا — جاننے والا ہے — یعنی اللہ — حکمت سے — درجات دیتا ہے۔
۴۔ عملی سبق: اللہ کی عطا کردہ دلیل پر عمل کرو؛ درجات کی خواہش کرو؛ اللہ سے یقین مانگو۔"""
),
}
